# downside asymmetry: prefer assets whose recent returns have less downside than upside, with magnitude normalization
mu=R.rolling(20,min_periods=15).mean(); dn=R.clip(upper=0).rolling(20,min_periods=15).std(); up=R.clip(lower=0).rolling(20,min_periods=15).std()
F=(up-dn)/(R.rolling(20,min_periods=15).std()+1e-12)
# strict lag
F=F.shift(1)
for h in [1,5,10]:
 y=P.pct_change(h,fill_method=None).shift(-h); vals=[]; ns=[]
 for d in P.index:
  q=pd.concat([F.loc[d].rename('f'),y.loc[d].rename('y')],axis=1).dropna()
  if len(q)>=8 and q.f.nunique()>1: vals.append(spearmanr(q.f,q.y).statistic); ns.append(len(q))
 a=np.asarray(vals); print('H',h,'dates',len(a),'avgN',round(np.mean(ns),2),'IC',round(a.mean(),6),'ICIR',round(a.mean()/a.std(ddof=1),6),'hit',round((a>0).mean(),4))
print('coverage',F.notna().sum().sum()/F.size,'turnover',F.rank(axis=1,pct=True).diff().abs().mean().mean(),'period',P.index.min(),P.index.max())
for yr in range(2020,2027):
 z=[]
 y=P.pct_change(fill_method=None).shift(-1)
 for d in P.index[P.index.year==yr]:
  q=pd.concat([F.loc[d].rename('f'),y.loc[d].rename('y')],axis=1).dropna()
